    for ir,(r0,r1) in enumerate(rb):
      for ic,(c0,c1) in enumerate(cb):
       for r in range(r0,r1):
        for c in range(c0,c1):
         if grid[r][c] in marks: marks[grid[r][c]].append((ir,ic,r-r0,c-c0))
