        for r,c in pts:
            for x in range(m):
                if grid[r][x] not in (8,): out[r][x]=color
            for y in range(n):
                if grid[y][c] not in (8,): out[y][c]=color
    # Overlapping distinct color lines are shown as 6.
    for r in range(n):
        for c in range(m):
            if grid[r][c]==8: continue
            colors=set()
            for rr,cc in [(r,x) for x in range(m) if grid[r][x] in (2,3)]+[(y,c) for y in range(n) if grid[y][c] in (2,3)]:
                colors.add(grid[rr][cc])
            if len(colors)>1: out[r][c]=6
